SilphCo4F_SetCardKeyDoorYScript:
    push esi
    mov esi, wCardKeyDoorY
    mov al, [ebp + esi]
    lea esi, [esi+1]
    mov bh, al
    mov al, [ebp + esi]
    mov bl, al
    xor al, al
    mov [ebp + hUnlockedSilphCoDoors], al
    pop esi
.loop_check_doors:
    mov al, [esi]
    lea esi, [esi+1]
    cmp al, 0xff
    jz .exit_loop
    push esi
    mov esi, hUnlockedSilphCoDoors
    inc byte [ebp + esi]
    pop esi
    cmp al, bh
    jz .check_y_coord
    lea esi, [esi+1]
    jmp .loop_check_doors

