%assign event_byte_a -1
.check_y_coord:
    mov al, [esi]
    lea esi, [esi+1]
    cmp al, bl
    jnz .loop_check_doors
    mov esi, wCardKeyDoorY
    xor al, al
    mov [ebp + esi], al
    lea esi, [esi+1]
    mov [ebp + esi], al
    ret

%assign event_byte -1
%assign event_byte_a -1
.exit_loop:
    xor al, al
    mov [ebp + hUnlockedSilphCoDoors], al
    ret

%assign event_byte -1
